svg.script:
//
function a12p212hSetView(mode) {
  var viewPerv = document.getElementById('a12p21-2h-view-perv');
  var viewImperf = document.getElementById('a12p21-2h-view-imperf');
  var tabBoth = document.getElementById('a12p21-2h-tab-both');
  var tabPerv = document.getElementById('a12p21-2h-tab-perv');
  var tabImperf = document.getElementById('a12p21-2h-tab-imperf');

  // Reset Active Tabs
  tabBoth.classList.remove('a12p21-2h-active');
  tabPerv.classList.remove('a12p21-2h-active');
  tabImperf.classList.remove('a12p21-2h-active');

  if (mode === 'both') {
    tabBoth.classList.add('a12p21-2h-active');
    viewPerv.setAttribute('transform', 'translate(40, 135)');
    viewImperf.setAttribute('transform', 'translate(340, 135)');
    viewPerv.classList.remove('a12p21-2h-hidden');
    viewImperf.classList.remove('a12p21-2h-hidden');
    a12p212hUpdateReadout('both');
  } else if (mode === 'perv') {
    tabPerv.classList.add('a12p21-2h-active');
    viewPerv.setAttribute('transform', 'translate(180, 135)');
    viewPerv.classList.remove('a12p21-2h-hidden');
    viewImperf.classList.add('a12p21-2h-hidden');
    a12p212hUpdateReadout('perv');
  } else if (mode === 'imperf') {
    tabImperf.classList.add('a12p21-2h-active');
    viewImperf.setAttribute('transform', 'translate(180, 135)');
    viewImperf.classList.remove('a12p21-2h-hidden');
    viewPerv.classList.add('a12p21-2h-hidden');
    a12p212hUpdateReadout('imperf');
  }
}

function a12p212hUpdateReadout(type) {
  var badgeBg = document.getElementById('a12p21-2h-badge-bg');
  var badgeTxt = document.getElementById('a12p21-2h-badge-txt');
  var m1 = document.getElementById('a12p21-2h-m1-val');
  var m2 = document.getElementById('a12p21-2h-m2-val');
  var m3 = document.getElementById('a12p21-2h-m3-val');
  var l1 = document.getElementById('a12p21-2h-desc-line1');
  var l2 = document.getElementById('a12p21-2h-desc-line2');
  var l3 = document.getElementById('a12p21-2h-desc-line3');
  var l4 = document.getElementById('a12p21-2h-desc-line4');

  if (type === 'perv') {
    badgeBg.setAttribute('fill', 'var(--a12p21-2h-green-bg, rgba(34, 197, 94, 0.15))');
    badgeBg.setAttribute('stroke', 'var(--a12p21-2h-green, #22c55e)');
    badgeTxt.setAttribute('fill', 'var(--a12p21-2h-green, #22c55e)');
    badgeTxt.textContent = 'STATUS: ESCOAMENTO FISIOLÓGICO ATIVO';

    m1.textContent = 'Fenestrada / Pérvia com Óstio Central';
    m2.textContent = 'Escoamento Desimpedido (P < 5 mmHg)';
    m2.setAttribute('style', 'fill:var(--a12p21-2h-green, #22c55e)');
    m3.textContent = 'Canal Vaginal sem Distensão / Fisiológico';

    l1.textContent = 'Membrana himenal complacente com';
    l2.textContent = 'abertura anatômica preservada. Permite';
    l3.textContent = 'passagem contínua de secreções';
    l4.textContent = 'glandulares e fluxo sem resistência.';
  } else if (type === 'imperf') {
    badgeBg.setAttribute('fill', 'var(--a12p21-2h-red-bg, rgba(239, 68, 68, 0.15))');
    badgeBg.setAttribute('stroke', 'var(--a12p21-2h-red, #ef4444)');
    badgeTxt.setAttribute('fill', 'var(--a12p21-2h-red, #ef4444)');
    badgeTxt.textContent = 'STATUS: SAÍDA BLOQUEADA / RETENÇÃO';

    m1.textContent = 'Membrana Contínua Sem Óstio (Oclusiva)';
    m2.textContent = 'Hiperpressão Retrógrada (> 35 mmHg)';
    m2.setAttribute('style', 'fill:var(--a12p21-2h-red, #ef4444)');
    m3.textContent = 'Distensão de Lúmen / Acúmulo Fluido';

    l1.textContent = 'Membrana integra e oclusiva que impede';
    l2.textContent = 'a saída do fluxo. Causa acúmulo';
    l3.textContent = 'retrogrado de secreção (mucocolpos /';
    l4.textContent = 'hematocolpos) e abaulamento vulvar.';
  } else {
    badgeBg.setAttribute('fill', 'var(--a12p21-2h-amber-bg, rgba(245, 158, 11, 0.15))');
    badgeBg.setAttribute('stroke', 'var(--a12p21-2h-amber, #f59e0b)');
    badgeTxt.setAttribute('fill', 'var(--a12p21-2h-amber, #f59e0b)');
    badgeTxt.textContent = 'STATUS: ANÁLISE COMPARATIVA DE FLUXO';

    m1.textContent = 'Pérvio (Apertura) vs Imperfurado (Bloqueio)';
    m2.textContent = 'Fluxo Livre vs Estase com Hiperpressão';
    m2.setAttribute('style', 'fill:var(--a12p21-2h-amber, #f59e0b)');
    m3.textContent = 'Vagina Complacente vs Distensão Luminal';

    l1.textContent = 'Compare a transição mecânica: no hímen';
    l2.textContent = 'pérvio, o vetor atravessa o óstio; no';
    l3.textContent = 'imperfurado, a membrana contínua reflete';
    l4.textContent = 'o vetor e gera expansão retrógrada.';
  }
}

function a12p212hShowInfo(target) {
  if (target === 'perv-hymen' || target === 'perv-flow') {
    a12p212hSetView('perv');
  } else if (target === 'imperf-hymen' || target === 'imperf-retention') {
    a12p212hSetView('imperf');
  }
}
//
